import { describe, expect, it } from "vitest";
// Generated by backend/tests/physics_vectors.py from the Python physics module.
import vectors from "../../../../shared/physics-test-vectors.json";
import {
  DEFAULT_CRR,
  DEFAULT_EFFICIENCY,
  DEFAULT_ROTATING_MASS_KG,
  DEFAULT_START_FORCE_N,
  DEFAULT_START_POWER_RATIO,
  G,
  SIMULATION_STEP_S,
  airDensity,
  cadenceFromSpeedRpm,
  developmentM,
  gearInches,
  powerForTimeW,
  powerRequiredW,
  simulate,
  speedFromCadenceMs,
  steadySpeedMs,
  type EffortOptions,
  type Setup,
} from "./physics";

type SetupName = keyof typeof vectors.setups;
type EffortCase = {
  standing: boolean;
  split_every_m?: number;
  start_power_ratio?: number;
  start_force_n?: number;
};

function setup(name: string): Setup {
  const s = vectors.setups[name as SetupName];
  return {
    massKg: s.mass_kg,
    cdaM2: s.cda_m2,
    rho: s.rho,
    crr: s.crr,
    efficiency: s.efficiency,
    rotatingMassKg: s.rotating_mass_kg,
  };
}

function options(c: EffortCase): EffortOptions {
  return {
    standing: c.standing,
    splitEveryM: c.split_every_m ?? null,
    startPowerRatio: c.start_power_ratio,
    startForceN: c.start_force_n,
  };
}

/** Same algorithm and constants on both sides, so only float noise may differ. */
function expectClose(actual: number, expected: number) {
  expect(Math.abs(actual - expected)).toBeLessThanOrEqual(1e-9 * Math.max(1, Math.abs(expected)));
}

describe("physics.ts matches the Python model (shared vectors)", () => {
  it("uses the same constants", () => {
    expect({
      G,
      DEFAULT_CRR,
      DEFAULT_EFFICIENCY,
      DEFAULT_ROTATING_MASS_KG,
      DEFAULT_START_POWER_RATIO,
      DEFAULT_START_FORCE_N,
      SIMULATION_STEP_S,
    }).toEqual(vectors.constants);
  });

  it.each(vectors.air_density)("air density %#", (c) => {
    expectClose(
      airDensity(c.temp_c, {
        pressurePa: c.pressure_pa,
        elevationM: c.elevation_m,
        humidityPct: c.humidity_pct,
      }),
      c.expected,
    );
  });

  it.each(vectors.power_required)("power required %#", (c) => {
    expectClose(powerRequiredW(c.speed_ms, setup(c.setup), c.accel_ms2), c.expected);
  });

  it.each(vectors.steady_speed)("steady speed %#", (c) => {
    expectClose(steadySpeedMs(c.power_w, setup(c.setup)), c.expected);
  });

  it.each(vectors.simulate)("simulate %#", (c) => {
    const ride = simulate(c.distance_m, c.power_w, setup(c.setup), options(c));
    expect(ride).not.toBeNull();
    expectClose(ride!.timeS, c.expected.time_s);
    expectClose(ride!.finalSpeedMs, c.expected.final_speed_ms);
    expectClose(ride!.averagePowerW, c.expected.average_power_w);
    expect(ride!.splitTimesS).toHaveLength(c.expected.split_times_s.length);
    ride!.splitTimesS.forEach((t, i) => expectClose(t, c.expected.split_times_s[i]));
  });

  it.each(vectors.power_for_time)("power for time %#", (c) => {
    const power = powerForTimeW(c.distance_m, c.time_s, setup(c.setup), options(c));
    if (c.expected === null) expect(power).toBeNull();
    else expect(power).toBeCloseTo(c.expected, 6);
  });

  it.each(vectors.gearing)("gearing %#", (c) => {
    expectClose(developmentM(c.chainring, c.cog, c.rollout_m), c.expected.development_m);
    expectClose(gearInches(c.chainring, c.cog, c.rollout_m), c.expected.gear_inches);
    expectClose(speedFromCadenceMs(c.cadence_rpm, c.chainring, c.cog, c.rollout_m), c.expected.speed_ms);
    expectClose(cadenceFromSpeedRpm(c.speed_ms, c.chainring, c.cog, c.rollout_m), c.expected.cadence_rpm);
  });
});

describe("physics.ts", () => {
  it("rides a flying effort at steady speed", () => {
    const s = setup("pursuiter");
    const ride = simulate(4000, 450, s, { standing: false })!;
    expect(ride.timeS).toBeCloseTo(4000 / steadySpeedMs(450, s), 6);
  });

  it("leaves a stalled rider standing still", () => {
    expect(simulate(250, 300, setup("pursuiter"), { startForceN: 1 })).toBeNull();
  });
});
